<template><main class="screen"><header><RouterLink to="/dashboard">‹</RouterLink><b>Plan de table</b><button class="add">＋</button></header><div class="tabs"><b>Aperçu</b><span>Tables</span><span>Invités</span></div><div class="honor">🌿　 Table d'honneur　 🌿</div><div class="tables"><div v-for="n in 6" :key="n" class="table"><span>{{n}}</span><i v-for="x in 8" :key="x" :style="{transform:'rotate('+((x-1)*45)+'deg) translateY(-28px)'}"></i></div></div><div class="draft">Version brouillon <b>Voir en taille réelle</b></div><Nav/></main></template><style scoped>.tabs{display:flex;justify-content:space-around;padding:12px 0 9px;font-size:6.5px}.tabs b{color:#df3b72;border-bottom:2px solid #ed4a80;padding-bottom:7px}.honor{text-align:center;border:1px solid #ee9bb5;border-radius:7px;padding:6px;font-size:6px;color:#df3b72}.tables{display:grid;grid-template-columns:repeat(3,1fr);gap:21px 12px;padding:25px 8px 26px}.table{width:45px;height:45px;border:1px solid #c9b5b1;border-radius:50%;margin:auto;position:relative;display:grid;place-items:center}.table span{font-size:7px}.table i{position:absolute;top:50%;left:50%;width:6px;height:6px;border-radius:50%;background:#ded0cc;transform-origin:center 28px}.draft{border:1px solid #f0e5e5;border-radius:8px;padding:11px;font-size:6.5px}.draft b{float:right;color:#df3b72;font-weight:400}</style>